#include <iostream>
#include "DX12/ObjMeshLoader.h"
int main(){ ObjMeshData m; if(!ObjLoader::LoadObjPosNormal(L"x64/Debug/Models/sponza.obj", m, true)){ std::cout<<"load fail\n"; return 1;} XMFLOAT3 mn=m.Vertices[0].Pos, mx=m.Vertices[0].Pos; for(auto &v:m.Vertices){ mn.x=std::min(mn.x,v.Pos.x); mn.y=std::min(mn.y,v.Pos.y); mn.z=std::min(mn.z,v.Pos.z); mx.x=std::max(mx.x,v.Pos.x); mx.y=std::max(mx.y,v.Pos.y); mx.z=std::max(mx.z,v.Pos.z);} float maxSize=std::max(mx.x-mn.x,std::max(mx.y-mn.y,mx.z-mn.z)); float scale=250.0f/maxSize; std::cout<<"verts "<<m.Vertices.size()<<" idx "<<m.Indices.size()<<"\n"; std::cout<<"min "<<mn.x<<" "<<mn.y<<" "<<mn.z<<" max "<<mx.x<<" "<<mx.y<<" "<<mx.z<<" scale "<<scale<<"\n"; std::cout<<"scaled size "<<(mx.x-mn.x)*scale<<" "<<(mx.y-mn.y)*scale<<" "<<(mx.z-mn.z)*scale<<"\n"; }
